import { GetItemCommand } from 'dynamodb-toolbox/entity/actions/get';
import { QueryCommand } from 'dynamodb-toolbox/table/actions/query';
import { MODELO_AULA, MODELO_ESCUELA, TABLA_AULAS } from '../../models/escuela-aula.model.mjs';

export async function buscarEscuelaRepository(escuelaId) {
  const { Item } = await MODELO_ESCUELA.build(GetItemCommand)
    .key({ escuelaId }).options({ consistent: true }).send();
  return Item ?? null;
}

export async function consultarEscuelaRepository(escuelaId, minimo) {
  const { Items = [] } = await TABLA_AULAS.build(QueryCommand)
    .entities(MODELO_AULA)
    .query({ index: 'PorEscuela', partition: escuelaId })
    .options({ filters: { Aula: { attr: 'capacidad', gte: minimo } } })
    .send();
  return Items;
}
